	"os"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	var x int64
	anyNonZero := false
	for i := 0; i < n; i++ {
		v := nextInt()
		x ^= v
		if v != 0 {
			anyNonZero = true
		}
	}
	// Zero already: 0; total XOR zero: one whole-array operation; else two.
	switch {
	case !anyNonZero:
		fmt.Println(0)
	case x == 0:
		fmt.Println(1)
	default:
		fmt.Println(2)
	}
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
